files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #fffafa;
  --vt-surface-deep: #2a2a2a;
  --vt-ink: #2a2a2a;
  --vt-ink-soft: #6d6d6d;
  --vt-on-deep: #ffffff;
  --vt-accent: #b02a20;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #b02a20;
  --vt-accent-on-deep: #fb5849;
  --vt-line: #dddddd;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root {
  font-family: 'Poppins', sans-serif;
  color: var(--vt-ink);
  background-color: var(--vt-surface);
  line-height: 1.6;
}

.root a {
  text-decoration: none;
}

.root img {
  max-width: 100%;
  display: block;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* Navigation */
.nav {
  background-color: var(--vt-surface);
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  height: 80px;
  box-shadow: 0 0 10px rgba(0,0,0,0.1);
}

.navIn {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.logo {
  display: flex;
  align-items: center;
}

.brand {
  font-size: 28px;
  font-weight: 700;
  color: var(--vt-ink);
}

.navLinks a {
  margin-left: 25px;
  font-size: 15px;
  font-weight: 600;
  color: var(--vt-ink);
  transition: color 0.3s;
}

.navLinks a:hover {
  color: var(--vt-accent);
}

/* Hero */
.hero {
  display: flex;
  align-items: stretch;
  min-height: 600px;
  padding-top: 80px;
}

.heroLeft {
  flex: 0 0 40%;
  background-color: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 40px;
}

.heroBrand {
  margin-bottom: 20px;
  color: var(--vt-on-deep);
}

.heroKicker {
  font-family: 'Dancing Script', cursive;
  font-size: 54px;
  font-weight: 700;
  color: var(--vt-on-deep);
  margin: 0;
}

.heroWord {
  font-size: 15px;
  text-transform: uppercase;
  letter-spacing: 3px;
  color: var(--vt-on-deep);
  margin: 10px 0 25px;
}

.heroCta {
  display: inline-block;
  background-color: var(--vt-on-deep);
  color: var(--vt-accent);
  padding: 12px 25px;
  border-radius: 3px;
  font-weight: 600;
  transition: opacity 0.3s;
}

.heroCta:hover {
  opacity: 0.9;
}

.heroRight {
  flex: 1;
  min-width: 0;
}

.heroImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* About */
.about {
  padding: 100px 0;
}

.aboutInner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
  display: flex;
  gap: 40px;
}

.aboutText {
  flex: 1;
}

.aboutImageWrap {
  flex: 1;
}

.sectionLabel {
  font-size: 15px;
  color: var(--vt-accent);
  font-weight: 500;
  letter-spacing: 2px;
  text-transform: uppercase;
  padding-left: 40px;
  position: relative;
  margin: 0;
}

.sectionLabel::before {
  content: '';
  position: absolute;
  left: 0;
  top: 8px;
  width: 30px;
  height: 1px;
  background-color: var(--vt-accent);
}

.sectionTitle {
  font-size: 30px;
  font-weight: 900;
  line-height: 1.3;
  margin: 20px 0 25px;
  color: var(--vt-ink);
}

.aboutIntro {
  margin-bottom: 15px;
  color: var(--vt-ink-soft);
  line-height: 1.7;
}

.aboutThumbs {
  display: flex;
  gap: 10px;
  margin-top: 30px;
}

.aboutThumb {
  width: calc(33.333% - 7px);
  height: auto;
  border-radius: 3px;
}

.aboutImage {
  width: 100%;
  border-radius: 3px;
}

/* Menu Cards */
.menu {
  background-color: var(--vt-surface-2);
  padding: 120px 0;
}

.menuHeader {
  max-width: 1200px;
  margin: 0 auto 60px;
  padding: 0 20px;
}

.menuGrid {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
}

.menuCard {
  position: relative;
  flex: 1 1 calc(20% - 20px);
  min-width: 200px;
  min-height: 400px;
  background-color: var(--vt-surface);
  border: 1px solid var(--vt-line);
  border-radius: 3px;
  overflow: hidden;
  transition: transform 0.3s;
}

.menuCard:hover {
  transform: translateY(-5px);
}

.priceBadge {
  position: absolute;
  top: 0;
  right: 0;
  width: 70px;
  height: 70px;
  background-color: var(--vt-accent);
  color: var(--vt-on-accent);
  font-size: 20px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 0 0 0 3px;
}

.menuInfo {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 20px;
  background-color: var(--vt-surface);
  border-top: 1px solid var(--vt-line);
}

.menuItemTitle {
  font-size: 20px;
  font-weight: 700;
  color: var(--vt-ink);
  margin: 0 0 10px;
}

.menuItemDesc {
  font-size: 14px;
  color: var(--vt-ink-soft);
  margin: 0;
}

/* Offers */
.offers {
  padding: 120px 0;
}

.offersHeader {
  max-width: 1200px;
  margin: 0 auto 60px;
  padding: 0 20px;
  text-align: center;
}

.offersList {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

.offerItem {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 0;
  border-bottom: 1px solid var(--vt-line);
}

.offerText h4 {
  font-size: 20px;
  font-weight: 700;
  color: var(--vt-ink);
  margin: 0 0 10px;
}

.offerText p {
  font-size: 14px;
  color: var(--vt-ink-soft);
  margin: 0;
}

.offerPrice {
  flex-shrink: 0;
  width: 70px;
  height: 70px;
  background-color: var(--vt-accent);
  color: var(--vt-on-accent);
  font-size: 18px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 3px;
}

/* Contact */
.contact {
  background-color: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 120px 0;
}

.contactInner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
  display: flex;
  gap: 40px;
}

.contactInfo {
  flex: 1;
}

.sectionLabelDark {
  font-size: 15px;
  color: var(--vt-accent-on-deep);
  font-weight: 500;
  letter-spacing: 2px;
  text-transform: uppercase;
  padding-left: 40px;
  position: relative;
  margin: 0;
}

.sectionLabelDark::before {
  content: '';
  position: absolute;
  left: 0;
  top: 8px;
  width: 30px;
  height: 1px;
  background-color: var(--vt-accent-on-deep);
}

.sectionTitleDark {
  font-size: 30px;
  font-weight: 700;
  line-height: 1.3;
  margin: 20px 0 25px;
  color: var(--vt-on-deep);
}

.socialLinks {
  margin-top: 30px;
}

.contactCard {
  flex: 1;
  background-color: var(--vt-surface);
  color: var(--vt-ink);
  padding: 40px 30px;
  border-radius: 5px;
}

.contactCard h4 {
  font-size: 30px;
  font-weight: 700;
  text-align: center;
  margin-bottom: 30px;
}

.contactCard p {
  margin: 10px 0;
}

/* Footer */
.footer {
  background-color: var(--vt-accent);
  color: var(--vt-on-accent);
  padding: 50px 0;
}

.footerInner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
  text-align: center;
}

.footerSocial {
  margin-bottom: 20px;
}

.footer p {
  margin: 0;
  font-size: 14px;
}

/* Responsive */
@media (max-width: 991px) {
  .hero {
    flex-direction: column;
  }
  .heroLeft {
    flex: none;
    padding: 60px 20px;
  }
  .heroRight {
    flex: none;
  }
  .aboutInner,
  .contactInner {
    flex-direction: column;
  }
  .menuCard {
    flex: 1 1 100%;
    min-height: 300px;
  }
}

@media (max-width: 767px) {
  .nav {
    position: static;
    height: auto;
    padding: 15px 0;
  }
  .navIn {
    flex-direction: column;
  }
  .navLinks {
    margin-top: 10px;
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
  }
  .navLinks a {
    margin: 0 10px;
  }
  .hero {
    padding-top: 0;
  }
  .aboutThumbs {
    flex-wrap: wrap;
  }
  .aboutThumb {
    width: 100%;
  }
}
